from 写入第二遍 import add
add('15_001',1.5,'16:9，高处斜俯看屋顶街区；相机从近拳方向快速拉开，落在屋顶夹出的中心冲击点，白色放射形由中心向四周展开。','近拳命中后，冲击从两人所在的屋顶间骤然炸开，原先还可辨的碎砖轮廓被一道短促白色放射形吞住；烟尘沿屋面两侧摊开，外圈稍后抵到低屋檐，接着中心亮形迅速退成米灰翻尘。','蓝灰瓦屋面与灰米高墙围成街区纵深，中心米灰烟尘及白色放射冲击形依次扩展，未另添大面积建筑坍塌。','爆发瞬间的白亮为极短冲击替换画，随后回到天空冷白柔光与屋顶固有色。','一声低沉而硬的命中重响，紧接短爆风，砖屑密集散落，外圈回声迟到。',phase='result',node={'双方.距离':'被冲击烟尘隔开','青.阶段':'命中后开始脱离'},meaning='承接青一拳确实命中；俯瞰街区的大冲击保留，命中细节可在第三轮前插接触镜，原镜不能被替换。')
add('15_002',2,'16:9，天空横幅极远景，左侧冲击烟云占近半幅，白色弧线从其边缘向右伸出；镜头顺弧线向右缓摇，到连续螺旋圈和末端小身影即停。','青的身影从冲击烟云中向后退出，先沿长弧向远处拉开距离，身体带着后翻余势转过，长发拖出连续螺旋轨迹；她逐步把身体收回面向武士的方向，沿弧线末段下沉，尚未触地。','铅蓝云天，左侧米灰冲击烟云缓慢膨开，白色弧形及螺旋轨迹横过天空。','开阔天空冷白漫射，远处身影只读轮廓，轨迹是动作图形，不照亮云层。','近处爆风远去，青后退的旋风声从强转细，烟尘里余响拖尾。',phase='process',node={'青.阶段':'命中后向后退出并翻转下沉'},meaning='用户明确解释15_002是青的身影后退，随后接16_001滑退落地；此理解写入动作，远景图像本身仍不足独立认人。')
add('16_001',2.5,'16:9，略高机位全身中全景；青从近空落入，镜头向下摇并短距后退，落幅为她双腿张开、双拳收腰的滑退姿态；不继续推近脸。','青仍面向武士，双脚先后接上石铺地，膝盖压下吸住落势，鞋底沿后退方向拉出两道弯曲擦痕；她展开双腿把滑速压住，右拳从前方收回腰侧，另一拳同时立稳。头发越过肩头后摆落，她抬起脸，眉眼绷紧，嘴角刚扬起一点，滑动终于停住。','灰绿不规则石铺地占大部，细米灰尘沿两道滑痕向前掀起；远处被薄尘和冷白天空交界虚化。','开阔空地天空的冷白柔光从青后上方落下，地面有弱中性反光。','两下落脚闷响接连续鞋底刮地，滑速下降时摩擦声逐渐变粗后停，砂粒继续滚动。',phase='endpoint',node={'青.阶段':'后滑落地停稳','青.接触':'双脚接地','双方.距离':'相隔一段空地、烟尘居中'},meaning='按用户解释为青后退后的滑落地；原作大开步、拳收腰与擦痕关系保留。',pcard={'opening':'青正从后退弧线回落，仍面对对手。','beats':['双脚先后接地，膝下压','展开腿刹住滑动，收拳抬脸'],'coupling':'收拳和滑停同时形成下一拍对峙姿态。','landing':'身体停稳，发束与尘粒仍有余势。'})
